    'SoaChooseFramework' => 'Alegeți un cadru',
    'SoaChooseFrameworkHint' => 'O declarație de aplicabilitate este scrisă despre un cadru pe rând.',
    // The picker has a roster but nothing in it. Distinct from "this framework
